const test=require('node:test'),assert=require('node:assert/strict'),{OfficeIntegrations}=require('../src/office-integrations.cjs');
function fixture(attached=true){let closes=0,invalidated=0;const browser={attached,closed:false,frame:{},finalAuthorization:{},finalAttempts:new Set(['already-attempted']),invalidate(){invalidated++;},resetTask(){this.reset=true;}};const instance={browser,people:new Map([['old',1]]),windows:new Set([1]),pending:new Map([['old',1]]),approvedFiles:new Map([['old',1]]),async close(){closes++;if(this.browser)this.browser.closed=true;this.browser=null;}};const integration=new OfficeIntegrations({});integration.instance=instance;return {integration,instance,browser,closes:()=>closes,invalidated:()=>invalidated};}
test('switching conversations preserves an attached Chrome connection and duplicate guards while clearing task grants',async()=>{const f=fixture();await f.integration.reset({keepBrowser:true});assert.equal(f.instance.browser,f.browser);assert.equal(f.browser.closed,false);assert.equal(f.browser.frame,null);assert.equal(f.browser.finalAuthorization,null);assert(f.browser.finalAttempts.has('already-attempted'));assert.equal(f.invalidated(),1);assert.equal(f.closes(),1);for(const name of ['people','windows','pending','approvedFiles'])assert.equal(f.instance[name].size,0);});
test('explicit reset and dedicated-browser session switches still disconnect the browser',async()=>{for(const [attached,options]of [[true,{}],[false,{keepBrowser:true}]]){const f=fixture(attached);await f.integration.reset(options);assert.equal(f.instance.browser,null);assert.equal(f.browser.closed,true);}});
